## 2. Implement mTLS in Agent gRPC Server

**File: `internal/agent/server.go`**

Replace the insecure credentials setup (lines 59-63) with TLS configuration:

```go
// NewServer creates a new Pi Agent gRPC server
func NewServer(config *Config, logger logger.Interface, controllerClient pb.PiControllerServiceClient, nodeID string, tlsCAFile string) (*Server, error) {
    if config == nil {
        config = DefaultConfig()
    }

    // Create agent service
    agentService, err := NewAgentService(logger, controllerClient, nodeID)
    if err != nil {
        return nil, fmt.Errorf("failed to create agent service: %w", err)
    }

    // Configure gRPC server options
    var grpcOpts []grpc.ServerOption

    // Add mTLS if CA file is provided
    if tlsCAFile != "" && config.TLSCertFile != "" && config.TLSKeyFile != "" {
        cert, err := tls.LoadX509KeyPair(config.TLSCertFile, config.TLSKeyFile)
        if err != nil {
            return nil, fmt.Errorf("failed to load server TLS certificates: %w", err)
        }

        caCertPool := x509.NewCertPool()
        caPEM, err := os.ReadFile(tlsCAFile)
        if err != nil {
            return nil, fmt.Errorf("failed to read CA certificate: %w", err)
        }
        if !caCertPool.AppendCertsFromPEM(caPEM) {
            return nil, fmt.Errorf("failed to append CA certificate to pool")
        }

        tlsConfig := &tls.Config{
            Certificates: []tls.Certificate{cert},
            ClientCAs:    caCertPool,
            ClientAuth:   tls.RequireAndVerifyClientCert,
            MinVersion:   tls.VersionTLS12,
        }

        creds := credentials.NewTLS(tlsConfig)
        grpcOpts = append(grpcOpts, grpc.Creds(creds))
        logger.Info("Agent gRPC server configured with mutual TLS (mTLS)")
    } else {
        grpcOpts = append(grpcOpts, grpc.Creds(insecure.NewCredentials()))
        logger.Warn("Agent gRPC server running without TLS - development mode only")
    }

    // Add interceptors
    grpcOpts = append(grpcOpts,
        grpc.UnaryInterceptor(loggingInterceptor(logger)),
        grpc.StreamInterceptor(streamLoggingInterceptor(logger)),
    )

    grpcServer := grpc.NewServer(grpcOpts...)
    pb.RegisterPiAgentServiceServer(grpcServer, agentService)

    server := &Server{
        address:      config.GetAddress(),
        logger:       logger.WithField("component", "agent-server"),
        server:       grpcServer,
        agentService: agentService,
        config:       config,
        nodeID:       nodeID,
    }

    return server, nil
}
```

